import React, { useState } from "react";
import { Box, Button, Grid, TextField, Typography } from "@mui/material";
import { createTheme, ThemeProvider } from "@mui/material/styles";

function ContactForm() {
  const [form, setForm] = useState({
    name: "",
    email: "",
    message: "",
  });

  const [loading, setLoading] = useState(false);
  const focusedColor = "#8C52FF";
  const theme = createTheme({
    typography: {
      fontFamily: "'Poppins', sans-serif",
    },
    components: {
      MuiButton: {
        styleOverrides: {
          root: {
            backgroundColor: "#FFFFFF",
            color: "#8C52FF",
            fontWeight: "bold",
            padding: "10px 22px",
            "&:hover": {
              backgroundColor: focusedColor,
              color: "#FFFFFF",
            },
          },
        },
      },
      MuiTextField: {
        styleOverrides: {
          root: {
            "& label.Mui-focused": {
              color: focusedColor,
            },
            "& .MuiInput-underline:after": {
              borderBottomColor: focusedColor,
            },
            "& .MuiFilledInput-underline:after": {
              borderBottomColor: focusedColor,
            },
            "& .MuiOutlinedInput-root": {
              "& fieldset": {
                borderRadius: 20, // Apply borderRadius to all states
              },
              "&:hover fieldset": {
                borderColor: focusedColor, // Change border color on hover
              },
              "&.Mui-focused fieldset": {
                borderColor: focusedColor, // Change border color when focused
              },
            },
          },
        },
      },
    },
  });
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm({
      ...form,
      [name]: value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setLoading(true);

    setTimeout(() => {
      setForm({
        name: "",
        email: "",
        message: "",
      });
      setLoading(false);
    }, 2000); // Simulated delay for 2 seconds
  };

  const commonStyles = {
    fontFamily: "League Spartan, sans-serif",
    fontSize: "22px",
    fontWeight: "bold",
  };
  return (
    <ThemeProvider theme={theme}>
      <Box
        sx={{
          ...commonStyles,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          backgroundColor: "#f5f5f5", // Light grey background
          padding: 3,
          borderRadius: 5,
          boxShadow: "0px 0px 10px rgba(0, 0, 0, 0.1)",
          maxWidth: "500px",
          margin: "50px 0 50px 0",
          width: "100%",
        }}
      >
        {/* Heading outside the form but inside the container for overall alignment */}
        <Typography
          variant="h3"
          sx={{
            fontFamily: "League Spartan, sans-serif",
            fontWeight: "bold", // Assuming you want the bold weight; adjust as necessary
            margin: "20px", // gutterBottom equivalent, adjust the value as needed
            color: "text.primary", // Use theme's color
          }}
          gutterBottom
        >
          Contact Us
        </Typography>

        {/* Form container */}
        <Box
          component="form"
          onSubmit={handleSubmit}
          noValidate
          sx={{ mt: 1, width: "100%" }} // Ensure the form takes the full width of the container
        >
          <Grid container spacing={3} sx={{marginBottom: "20px"}}>
            <Grid item xs={12}>
              <TextField
                autoComplete="fname"
                name="name"
                required
                fullWidth
                id="name"
                label="Your Name"
                value={form.name}
                onChange={handleChange}
                variant="outlined"
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                required
                fullWidth
                id="email"
                label="Your Email"
                name="email"
                autoComplete="email"
                value={form.email}
                onChange={handleChange}
                variant="outlined"
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                required
                fullWidth
                name="message"
                label="Your Message"
                id="message"
                autoComplete="off"
                multiline
                rows={4}
                value={form.message}
                onChange={handleChange}
                variant="outlined"
              />
            </Grid>
          </Grid>
          <Button
            type="submit"
            fullWidth
            variant="contained"
            sx={{
              backgroundColor: "#8C52FF",
              "&:hover": { backgroundColor: "#7A45E5" },
              color: "white",
              mt: 2,
              textTransform: "none",
              width: '50%',
              borderRadius: "20px"
            }}
            size="large"
            disabled={loading}
          >
            {loading ? "Sending..." : "Send"}
          </Button>
        </Box>
      </Box>
    </ThemeProvider>
  );
}

export default ContactForm;
